{

"kind": "propose",
"summary": "Container 'api' in Deployment 'search' is throttled 81% of the time (nr_throttled=29160, limit=500m), causing readiness probe timeouts. Increasing CPU limit to 750m (1.5x current) should alleviate throttling.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Container 'api' is consistently throttled (81% of periods) despite using 498m of 500m limit. Readiness probes fail due to CPU-bound latency.",
    "supporting": ["ev-container_cpu", "ev-container_logs_tail", "ev-target_events"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search", "uid": "uid-deployment-search"},
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raise CPU limit to 750m, reducing throttling and improving readiness probe success rate.",
  "rationale": "Container logs show 81% throttling at 500m limit. Increasing limit to 750m (1.5x current) should clear throttling without affecting memory, as no memory limits are mentioned. Readiness probe failures correlate with CPU-bound latency in logs.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-container_cpu", "ev-target_events"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
